class FreqStack {
  private items: number[] = [];
  private count = new Map<number, number>();

  push(val: number): void {
    this.items.push(val);
    this.count.set(val, (this.count.get(val) ?? 0) + 1);
  }

  pop(): number {
    let best = 0;
    for (const c of this.count.values()) best = Math.max(best, c);
    for (let i = this.items.length - 1; ; i--) {
      const v = this.items[i];
      if (this.count.get(v) === best) {
        this.items.splice(i, 1);
        this.count.set(v, best - 1);
        return v;
      }
    }
  }
}

