class FreqStack {
  private count = new Map<number, number>();
  private layers: number[][] = [[]]; // layers[c] holds the c-th copies
  private top = 0;

  push(val: number): void {
    const c = (this.count.get(val) ?? 0) + 1;
    this.count.set(val, c);
    if (c === this.layers.length) this.layers.push([]);
    this.layers[c].push(val);
    if (c > this.top) this.top = c;
  }

  pop(): number {
    const val = this.layers[this.top].pop()!;
    this.count.set(val, this.count.get(val)! - 1);
    if (this.layers[this.top].length === 0) this.top--;
    return val;
  }
}

