    def __init__(self):
        self.count = defaultdict(int)
        self.layers = defaultdict(list)  # layers[c] holds the c-th copies
        self.top = 0

    def push(self, val: int) -> None:
        self.count[val] += 1
        c = self.count[val]
        self.layers[c].append(val)
        self.top = max(self.top, c)

    def pop(self) -> int:
        val = self.layers[self.top].pop()
        self.count[val] -= 1
        if not self.layers[self.top]:
            self.top -= 1
        return val

